<?php
$root=dirname(__DIR__);chdir($root);require 'vendor/autoload.php';$app=require 'bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();if(config('database.default')!=='sqlite'||!str_contains((string)config('database.connections.sqlite.database'),'saudi'))throw new RuntimeException('Saudi database required');$file=$root.'/content/saudi/2026-10-26/shared-service-articles.json';$posts=json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR);if(count($posts)!==7)throw new RuntimeException('Expected seven articles');foreach($posts as$p){if(App\Models\BlogPost::where('slug',$p['slug'])->exists())throw new RuntimeException('Existing article must not be overwritten: '.$p['slug']);if(!is_file(public_path(ltrim($p['image'],'/'))))throw new RuntimeException('Cover missing');foreach(['body','body_ar']as$k)if(count($p[$k])<15)throw new RuntimeException('Incomplete article');}if(!in_array('--apply',$argv,true)){echo json_encode(['mode'=>'dry-run','new_articles'=>count($posts),'existing_articles'=>App\Models\BlogPost::count(),'slugs'=>array_column($posts,'slug')],JSON_PRETTY_PRINT).PHP_EOL;exit;}$db=Illuminate\Support\Facades\DB::connection();$before=$db->table('blog_posts')->orderBy('id')->get()->toArray();$tables=['billboards','billboard_images','services','locations','settings','projects','users','suppliers'];$hash=[];foreach($tables as$t)$hash[$t]=hash('sha256',$db->table($t)->orderBy('id')->get()->toJson());$dir=storage_path('app/private/blog-import-backups');if(!is_dir($dir))mkdir($dir,0700,true);$backup=$dir.'/shared-services-'.gmdate('Ymd-His').'.json';file_put_contents($backup,json_encode($before,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));chmod($backup,0600);$sort=(int)App\Models\BlogPost::max('sort_order');$created=[];$db->transaction(function()use($db,$posts,$before,$tables,$hash,$sort,&$created){foreach($posts as$i=>$p){unset($p['sourceId'],$p['sourceSlug']);$p['published_at']=now();$p['sort_order']=$sort+$i+1;$created[]=App\Models\BlogPost::create($p)->id;}$ids=array_map(fn($r)=>$r->id,$before);if($db->table('blog_posts')->whereIn('id',$ids)->orderBy('id')->get()->toArray()!=$before)throw new RuntimeException('Existing articles changed');foreach($tables as$t)if(hash('sha256',$db->table($t)->orderBy('id')->get()->toJson())!==$hash[$t])throw new RuntimeException('Protected data changed: '.$t);});echo json_encode(['created'=>count($created),'ids'=>$created,'existing_articles_preserved'=>count($before),'total_articles'=>App\Models\BlogPost::count(),'backup'=>$backup],JSON_PRETTY_PRINT).PHP_EOL;